public class Account : AggregateRoot
{
    public decimal Balance { get; private set; }

    // Parameterless constructor for event sourcing
    private Account() {}

    public static Account Open(AccountId id, CustomerId owner)
    {
        var account = new Account();
        account.RaiseEvent(new AccountOpened(id, owner, DateTime.UtcNow));
        return account;
    }

    public void Credit(decimal amount, string reference)
    {
        if (amount <= 0) throw new ArgumentException("Amount must be positive");
        RaiseEvent(new AccountCredited(Id, amount, reference, DateTime.UtcNow));
    }

    public void Debit(decimal amount)
    {
        if (amount <= 0) throw new ArgumentException("Amount must be positive");
        if (Balance - amount < 0) throw new InvalidOperationException("Insufficient funds");
        RaiseEvent(new AccountDebited(Id, amount, DateTime.UtcNow));
    }

    // Apply events to rebuild state
    private void Apply(AccountOpened e) { Id = e.AccountId; Balance = 0; }
    private void Apply(AccountCredited e) { Balance += e.Amount; }
    private void Apply(AccountDebited e) { Balance -= e.Amount; }
}

