public record CreateOrderCommand(
    CustomerId CustomerId, ShippingAddress Address, List<OrderItemDto> Items)
    : IRequest<OrderId>;

public class CreateOrderHandler : IRequestHandler<CreateOrderCommand, OrderId>
{
    private readonly IOrderRepository _repo;
    private readonly IPublisher _publisher;

    public async Task<OrderId> Handle(CreateOrderCommand cmd, CancellationToken ct)
    {
        var order = Order.Create(OrderId.New(), cmd.CustomerId, cmd.Address);
        foreach (var item in cmd.Items)
            order.AddItem(item.ProductId, item.Price, item.Quantity);
        order.Confirm(); // enforces invariants
        _repo.Add(order);
        await _repo.UnitOfWork.SaveChangesAsync(ct);
        return order.Id;
    }
}

// Validation pipeline behavior
public class ValidationBehavior<TCommand> : IPipelineBehavior<TCommand, Unit>
    where TCommand : IRequest<Unit>
{
    private readonly IEnumerable<AbstractValidator<TCommand>> _validators;

    public async Task<Unit> Handle(TCommand request, RequestHandlerDelegate<Unit> next,
        CancellationToken ct)
    {
        var failures = _validators
            .Select(v => v.Validate(request))
            .SelectMany(result => result.Errors)
            .Where(f => f != null)
            .ToList();
        if (failures.Any()) throw new ValidationException(failures);
        return await next();
    }
}
